// centinela.panel100.integration · Patch C
// Reglas:
//   1) injectPanel100() no dispara descarga al final.
//   2) downloadFile() ya NO usa document.documentElement.outerHTML.
//   3) downloadFile() NO inventa window.__FORGE_WB__ / __FORGE_LAST_TX__
//      (esos no existen durante _weld() — el txResult committed no se
//       produce hasta después de que injectPanel100() retorna).
//   4) downloadFile() se queda como stub que emite panel100.downloaded
//      con ok:false y razón explícita. Si en el futuro ForgeContext
//      expone un capability real de exportación post-commit, se conecta ahí.

const injectPanel100 = function() {
  const configView = document.getElementById('v-config');
  if (!configView) {
    ctx.events.emit('panel100.error', { error: 'No se encontró la vista de configuración de Core-Termux' });
    return;
  }
  if (document.getElementById('p100-container')) {
    ctx.events.emit('panel100.already_injected');
    return;
  }
  const container = document.createElement('div');
  container.id = 'p100-container';
  container.className = 'p100-shell';
  container.style.cssText = 'padding: var(--pad); display: flex; flex-direction: column; gap: 12px;';
  container.innerHTML = `
    <div class="view-h" style="color: var(--cyan);">
      <span>📦 Panel 100 · core-termux mirror</span>
      <span class="pill cyan">F3.5.4-LIVE</span>
    </div>
    <div class="view-sub">Espejo operacional del repositorio DevCoreXOfficial/core-termux</div>
    <div class="stats-grid" id="p100-stats"></div>
    <div class="split">
      <div class="card"><div class="card-h">🔗 Dependencias <span class="badge" id="p100-deps-count">0</span></div><div id="p100-deps-list"></div></div>
      <div class="card"><div class="card-h">🤖 AI Catalog <span class="badge" id="p100-ai-count">0</span></div><div id="p100-ai-list"></div></div>
    </div>
    <div class="card"><div class="card-h">⚡ Comandos CLI <span class="badge" id="p100-cli-count">0</span></div><div id="p100-cli-list"></div></div>
    <div class="notice success">Panel 100 integrado como espejo operativo. Datos reales desde GitHub.</div>
  `;
  configView.appendChild(container);

  const repo = require('centinela.repoAnalyzer');
  if (repo && repo.cache) {
    const data = repo.cache;
    const stats = data.stats || {};
    const deps = data.deps || [];
    const ai = data.aiCatalog || [];
    const cli = data.cliCommands || [];

    const statsEl = document.getElementById('p100-stats');
    if (statsEl) {
      statsEl.innerHTML = `
        <div class="stat"><div class="stat-l">📄 Archivos</div><div class="stat-v">${stats.totalFiles || 0}</div></div>
        <div class="stat blue"><div class="stat-l">🔗 Dependencias</div><div class="stat-v">${stats.totalDeps || 0}</div></div>
        <div class="stat purple"><div class="stat-l">🤖 AI Tools</div><div class="stat-v">${stats.totalAi || 0}</div></div>
        <div class="stat green"><div class="stat-l">⚡ Comandos</div><div class="stat-v">${stats.totalCommands || 0}</div></div>
      `;
    }

    const depsList = document.getElementById('p100-deps-list');
    const depsCount = document.getElementById('p100-deps-count');
    if (depsCount) depsCount.textContent = deps.length;
    if (depsList) {
      depsList.innerHTML = deps.slice(0, 30).map(d => `
        <div class="dep-row clickable">
          <span class="dep-name">${d.name}</span>
          <span class="dep-ver">${d.version || '?'}</span>
          <span class="dep-type">${d.type || ''}</span>
          <span class="dep-state ${d.version ? 'declared' : 'unknown'}">${d.version ? '📌 DECLARED' : '⚪ UNKNOWN'}</span>
        </div>
      `).join('') || '<div class="empty">Sin dependencias.</div>';
    }

    const aiList = document.getElementById('p100-ai-list');
    const aiCount = document.getElementById('p100-ai-count');
    if (aiCount) aiCount.textContent = ai.length;
    if (aiList) {
      aiList.innerHTML = ai.map(t => `
        <div class="ai-row">
          <div class="left"><span class="name">${t.nombre}</span><span class="flag">--${t.flag}</span></div>
          <div class="right">${(t.sha||'').substring(0,7)}</div>
        </div>
      `).join('') || '<div class="empty">Sin AI tools.</div>';
    }

    const cliList = document.getElementById('p100-cli-list');
    const cliCount = document.getElementById('p100-cli-count');
    if (cliCount) cliCount.textContent = cli.length;
    if (cliList) {
      cliList.innerHTML = cli.map(c => `<span class="chip">${c.name}</span>`).join('') || '<div class="empty">Sin comandos.</div>';
    }

    ctx.events.emit('panel100.loaded', { stats, deps: deps.length, ai: ai.length, cli: cli.length });
  }
  // Patch C: NO se llama a downloadFile() al final. La inyección del panel
  // no produce ningún artefacto. La exportación canónica la dispara
  // ForgeWeldExport tras txEngine.commit().
};

const downloadFile = function() {
  // Patch C: downloadFile() ya no es un mecanismo de descarga paralelo.
  // No usa document.documentElement.outerHTML. No construye un Blob del DOM.
  // No delega a ForgeWeldExport.exportCommittedWeld (durante _weld() no hay
  // txResult committed, y desde el módulo no tenemos acceso al workbench).
  //
  // Si en el futuro ForgeContext expone un capability real de exportación
  // post-commit, este stub se conecta ahí. Por ahora, emite
  // panel100.downloaded con ok:false y razón explícita.
  ctx.events.emit('panel100.downloaded', {
    ok: false,
    reason: 'downloadFile() deshabilitado por Patch C. La exportación canónica del commit la realiza ForgeWeldExport, no el módulo. Pulse "Soldar Módulos" en el Forge Workbench para obtener el artefacto forge-soldado-*.html.'
  });
};

try { injectPanel100(); } catch(e) { ctx.events.emit('panel100.error', { error: e.message }); }
